import { PACKAGE_NAME } from '../constants.js';
import { buildModelMetaSnapshot, buildViewMetaSnapshot } from './model-meta.js';
import { getClientExportName, TypeGenerator } from './type-generator.js';
export class DbClientGenerator {
    schema;
    constructor(schema) {
        this.schema = schema;
    }
    generate() {
        const modelImports = this.schema.models
            .flatMap((model) => [
            model.name,
            `${model.name}CreateInput`,
            `${model.name}UpdateInput`,
            `${model.name}WhereInput`,
            `${model.name}OrderByInput`,
            `${model.name}Include`,
        ])
            .join(',\n  ');
        const viewImports = this.schema.views
            .flatMap((view) => [view.name, `${view.name}WhereInput`, `${view.name}OrderByInput`])
            .join(',\n  ');
        const imports = [modelImports, viewImports].filter((block) => block.length > 0).join(',\n  ');
        const modelClientEntries = this.schema.models.map((model) => this.generateModelClientEntry(model.name));
        const viewClientEntries = this.schema.views.map((view) => this.generateViewClientEntry(view.name));
        const clientEntries = [...modelClientEntries, ...viewClientEntries];
        const metaHydrations = [
            ...this.schema.models.map((model) => {
                const clientKey = getClientExportName(model.name);
                return `  const ${clientKey}Meta = hydrateModelMeta(${clientKey}ModelMeta);`;
            }),
            ...this.schema.views.map((view) => {
                const clientKey = getClientExportName(view.name);
                return `  const ${clientKey}Meta = hydrateModelMeta(${clientKey}ModelMeta);`;
            }),
        ];
        const registryEntries = [
            ...this.schema.models.map((model) => {
                const clientKey = getClientExportName(model.name);
                return `    ['${model.name}', ${clientKey}Meta]`;
            }),
            ...this.schema.views.map((view) => {
                const clientKey = getClientExportName(view.name);
                return `    ['${view.name}', ${clientKey}Meta]`;
            }),
        ];
        const metaImportNames = [
            ...this.schema.models.map((model) => `${getClientExportName(model.name)}ModelMeta`),
            ...this.schema.views.map((view) => `${getClientExportName(view.name)}ModelMeta`),
        ];
        const hasModels = this.schema.models.length > 0;
        const hasViews = this.schema.views.length > 0;
        return [
            '// Auto-generated by DbClientGenerator. Do not edit manually.',
            "import type { Pool } from 'pg';",
            hasModels && hasViews
                ? `import { createModelClient, createReadOnlyModelClient } from '${PACKAGE_NAME}/db/model-client';`
                : hasViews
                    ? `import { createReadOnlyModelClient } from '${PACKAGE_NAME}/db/model-client';`
                    : `import { createModelClient } from '${PACKAGE_NAME}/db/model-client';`,
            `import { hydrateModelMeta } from '${PACKAGE_NAME}/db/model-meta';`,
            `import type { Queryable } from '${PACKAGE_NAME}/db/queryable';`,
            `import { createRawClient } from '${PACKAGE_NAME}/db/raw';`,
            `import { runInTransaction } from '${PACKAGE_NAME}/db/transaction';`,
            imports.length > 0 ? `import type {\n  ${imports},\n} from './db-types.js';` : '',
            metaImportNames.length > 0
                ? `import {\n  ${metaImportNames.join(',\n  ')},\n} from './db-model-meta.js';`
                : '',
            '',
            'function buildModels(executor: Queryable) {',
            ...metaHydrations,
            `  const modelRegistry = new Map([`,
            ...registryEntries.map((entry) => `    ${entry},`),
            '  ]);',
            '',
            '  return {',
            clientEntries.map((entry) => `    ${entry},`).join('\n'),
            '    ...createRawClient(executor),',
            '  };',
            '}',
            '',
            '/** All model clients scoped to a single transaction. Nested `$transaction` is unsupported. */',
            'export type TxClient = ReturnType<typeof buildModels>;',
            '',
            'export function createDbClient(pool: Pool) {',
            '  async function $transaction<T>(fn: (tx: TxClient) => Promise<T>): Promise<T> {',
            '    return runInTransaction(pool, (client) => fn(buildModels(client)));',
            '  }',
            '',
            '  return {',
            '    ...buildModels(pool),',
            '    $transaction,',
            '  };',
            '}',
            '',
            'export type DbClient = ReturnType<typeof createDbClient>;',
            '',
        ]
            .filter((line) => line !== '')
            .join('\n');
    }
    generateModelMetaModule() {
        const blocks = [
            ...this.schema.models.map((model) => {
                const meta = buildModelMetaSnapshot(model, this.schema);
                const clientKey = getClientExportName(model.name);
                return `export const ${clientKey}ModelMeta = ${JSON.stringify(meta, null, 2)} as const;`;
            }),
            ...this.schema.views.map((view) => {
                const meta = buildViewMetaSnapshot(view, this.schema);
                const clientKey = getClientExportName(view.name);
                return `export const ${clientKey}ModelMeta = ${JSON.stringify(meta, null, 2)} as const;`;
            }),
        ];
        return [
            '// Auto-generated model metadata. Do not edit manually.',
            `import type { ModelMetaSnapshot } from '${PACKAGE_NAME}/db/model-meta';`,
            '',
            ...blocks,
            '',
        ].join('\n');
    }
    generateModelClientEntry(modelName) {
        const clientKey = getClientExportName(modelName);
        return `${clientKey}: createModelClient<${modelName}, ${modelName}CreateInput, ${modelName}UpdateInput, ${modelName}WhereInput, ${modelName}OrderByInput>(${clientKey}Meta, executor, modelRegistry)`;
    }
    generateViewClientEntry(viewName) {
        const clientKey = getClientExportName(viewName);
        return `${clientKey}: createReadOnlyModelClient<${viewName}, ${viewName}WhereInput, ${viewName}OrderByInput>(${clientKey}Meta, executor)`;
    }
}
export function generateDbClientFiles(schema) {
    const typeGenerator = new TypeGenerator(schema);
    const dbClientGenerator = new DbClientGenerator(schema);
    return {
        dbTypes: typeGenerator.generate(),
        dbClient: dbClientGenerator.generate(),
        modelMeta: dbClientGenerator.generateModelMetaModule(),
    };
}
